{
  "name": "Soccer Academy Class Matcher",
  "description": "An AI-powered assistant that matches children to specific soccer classes based on age and location using the Soccer Academy schedule."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState } from 'react';
import { matchClass } from './services/geminiService';
import { MatchResult } from './types';
import { Loader2, Send, ShieldCheck, MapPin, Calendar, Info, AlertTriangle, CheckCircle2 } from 'lucide-react';

const App: React.FC = () => {
  const [input, setInput] = useState<string>('');
  const [loading, setLoading] = useState<boolean>(false);
  const [result, setResult] = useState<MatchResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim()) return;

    setLoading(true);
    setError(null);
    setResult(null);

    try {
      const data = await matchClass(input);
      setResult(data);
    } catch (err) {
      setError("We encountered an issue connecting to the AI coach. Please try again.");
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const renderStatusIcon = (status: string) => {
    switch (status) {
      case 'success':
        return <CheckCircle2 className="w-8 h-8 text-green-500" />;
      case 'missing_info':
        return <Info className="w-8 h-8 text-blue-500" />;
      case 'not_eligible':
      case 'location_unavailable':
      default:
        return <AlertTriangle className="w-8 h-8 text-amber-500" />;
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'success': return 'border-green-200 bg-green-50';
      case 'missing_info': return 'border-blue-200 bg-blue-50';
      default: return 'border-amber-200 bg-amber-50';
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-slate-50">
      {/* Header */}
      <header className="bg-gradient-to-r from-emerald-600 to-green-600 text-white shadow-lg sticky top-0 z-50">
        <div className="max-w-4xl mx-auto px-4 py-4 flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <ShieldCheck className="w-8 h-8" />
            <div>
              <h1 className="text-xl font-bold tracking-tight">Soccer Academy</h1>
              <p className="text-xs text-emerald-100 font-medium opacity-90">Class Matcher AI</p>
            </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-grow max-w-4xl w-full mx-auto px-4 py-8 flex flex-col md:flex-row gap-8">

        {/* Left Column: Input */}
        <div className="w-full md:w-1/2 flex flex-col space-y-6">
          <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
            <h2 className="text-lg font-semibold text-slate-800 mb-2">Find Your Class</h2>
            <p className="text-slate-500 text-sm mb-4">
              Tell us your child's <strong>age</strong> and your <strong>location</strong> (Duluth or Marietta).
            </p>

            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="relative">
                <textarea
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  placeholder="e.g., My son is 7 years old and we live in Duluth."
                  className="w-full min-h-[120px] p-4 rounded-xl border border-slate-300 focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 outline-none resize-none text-slate-700 placeholder:text-slate-400 transition-all"
                  disabled={loading}
                />
              </div>

              <div className="flex justify-end">
                <button
                  type="submit"
                  disabled={loading || !input.trim()}
                  className="flex items-center space-x-2 bg-emerald-600 hover:bg-emerald-700 disabled:bg-slate-300 disabled:cursor-not-allowed text-white font-medium py-2.5 px-6 rounded-lg transition-colors shadow-sm active:scale-95 transform duration-150"
                >
                  {loading ? (
                    <>
                      <Loader2 className="w-4 h-4 animate-spin" />
                      <span>Analyzing...</span>
                    </>
                  ) : (
                    <>
                      <span>Find Class</span>
                      <Send className="w-4 h-4" />
                    </>
                  )}
                </button>
              </div>
            </form>
          </div>

          {/* Example Prompts */}
          <div className="bg-slate-100 p-4 rounded-xl border border-slate-200">
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-3">Try asking:</p>
            <div className="space-y-2">
              <button 
                onClick={() => setInput("My daughter is 4 and we are near the Marietta complex.")}
                className="w-full text-left text-sm text-slate-600 bg-white p-2 rounded-md border border-slate-200 hover:border-emerald-300 hover:text-emerald-700 transition-colors"
              >
                "My daughter is 4 and we are near the Marietta complex."
              </button>
              <button 
                onClick={() => setInput("I have a 10 year old boy in Duluth. What classes are available?")}
                className="w-full text-left text-sm text-slate-600 bg-white p-2 rounded-md border border-slate-200 hover:border-emerald-300 hover:text-emerald-700 transition-colors"
              >
                "I have a 10 year old boy in Duluth."
              </button>
            </div>
          </div>
        </div>

        {/* Right Column: Output */}
        <div className="w-full md:w-1/2">
          {error && (
            <div className="bg-red-50 text-red-700 p-4 rounded-xl border border-red-200 flex items-start space-x-3">
              <AlertTriangle className="w-5 h-5 flex-shrink-0 mt-0.5" />
              <p>{error}</p>
            </div>
          )}

          {!result && !loading && !error && (
            <div className="h-full flex flex-col items-center justify-center text-slate-400 p-8 border-2 border-dashed border-slate-200 rounded-2xl">
              <ShieldCheck className="w-16 h-16 mb-4 opacity-20" />
              <p className="text-center">Enter your details to see the best soccer class schedule.</p>
            </div>
          )}

          {loading && !result && (
            <div className="h-full flex flex-col items-center justify-center space-y-4 p-8">
              <div className="w-full max-w-xs space-y-4 animate-pulse">
                <div className="h-4 bg-slate-200 rounded w-3/4 mx-auto"></div>
                <div className="h-32 bg-slate-200 rounded-xl"></div>
                <div className="h-4 bg-slate-200 rounded w-1/2 mx-auto"></div>
              </div>
            </div>
          )}

          {result && (
            <div className={`rounded-2xl border-2 p-6 shadow-sm ${getStatusColor(result.status)} transition-all duration-500 ease-out`}>
              <div className="flex items-start justify-between mb-6">
                <div>
                  <h3 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                    {result.status === 'success' ? 'Match Found!' : 
                     result.status === 'missing_info' ? 'More Info Needed' : 
                     'Availability Update'}
                  </h3>
                  <p className="text-sm text-slate-600 mt-1">
                    {result.status === 'success' ? 'We found a great class for your player.' : 'Please review the details below.'}
                  </p>
                </div>
                {renderStatusIcon(result.status)}
              </div>

              {/* Identified Details */}
              <div className="bg-white/60 rounded-xl p-4 mb-6 space-y-3">
                <div className="flex items-center text-sm">
                  <MapPin className="w-4 h-4 mr-3 text-slate-400" />
                  <span className="text-slate-500 w-20">Location:</span>
                  <span className="font-semibold text-slate-800">
                    {result.identified_location || <span className="text-amber-600 italic">Unknown</span>}
                  </span>
                </div>
                <div className="flex items-center text-sm">
                  <Calendar className="w-4 h-4 mr-3 text-slate-400" />
                  <span className="text-slate-500 w-20">Age:</span>
                  <span className="font-semibold text-slate-800">
                    {result.identified_age ? `${result.identified_age} years old` : <span className="text-amber-600 italic">Unknown</span>}
                  </span>
                </div>
              </div>

              {/* Recommendation */}
              {result.recommended_class_name && (
                <div className="mb-6">
                  <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">Recommended Class</h4>
