export default App;

export interface MatchResult {
  status: 'success' | 'missing_info' | 'not_eligible' | 'location_unavailable';
  identified_location: 'Duluth' | 'Marietta' | null;
  identified_age: number | null;
  recommended_class_name: string | null;
  recommended_options: string[];
  reply_message_en: string;
}

import { GoogleGenAI, Schema, Type } from "@google/genai";
import { MatchResult } from "../types";

const genAI = new GoogleGenAI({ apiKey: process.env.API_KEY });

const responseSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    status: {
      type: Type.STRING,
      enum: ["success", "missing_info", "not_eligible", "location_unavailable"],
      description: "The outcome of the match logic."
    },
    identified_location: {
      type: Type.STRING,
      enum: ["Duluth", "Marietta"],
      nullable: true,
      description: "The location extracted from user input."
    },
    identified_age: {
      type: Type.NUMBER,
      nullable: true,
      description: "The age extracted from user input."
    },
    recommended_class_name: {
      type: Type.STRING,
      nullable: true,
      description: "The name of the class (e.g. Tiny Kickers) if found."
    },
    recommended_options: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "List of available time slots for the class."
    },
    reply_message_en: {
      type: Type.STRING,
      description: "A polite, objective response message to the user in English."
    }
  },
  required: ["status", "recommended_options", "reply_message_en"]
};

const SYSTEM_INSTRUCTION = `
You are the "Class Matcher AI" for the Soccer Academy. Your function is to receive information about a child (age and location) and find the perfect class in our schedule.

**YOUR PERSONA:**
- You are objective, polite, and American.
- You do NOT invent times. Use ONLY the database below.

**DATABASE (SCHEDULE):**
1. LOCATION: DULUTH (Indoor Field)
   - "Tiny Kickers" (Ages 3-5): Tuesdays @ 5:00 PM | Thursdays @ 5:00 PM
   - "Junior Academy" (Ages 6-9): Mondays @ 6:00 PM | Wednesdays @ 6:00 PM
   - "Pro Development" (Ages 10-13): Fridays @ 6:30 PM

2. LOCATION: MARIETTA (Outdoor Complex)
   - "Tiny Kickers" (Ages 3-5): Saturdays @ 9:00 AM
   - "Junior Academy" (Ages 6-9): Saturdays @ 10:30 AM
   - "Pro Development" (Ages 10-13): Tuesdays @ 6:00 PM

**LOGIC RULES:**
1. If the child is an age we do not serve (e.g., < 3 or > 13), return status "not_eligible".
2. If the user location is not Duluth or Marietta, suggest the nearest or return "location_unavailable".
3. If information is missing (e.g., user said age but not location), return status "missing_info".
4. If a match is found, populate "recommended_class_name" and "recommended_options" strictly from the database.

**OUTPUT:**
You must return a valid JSON object matching the provided schema.
`;

export const matchClass = async (userInput: string): Promise<MatchResult> => {
  try {
    const model = "gemini-3-flash-preview";

    const response = await genAI.models.generateContent({
      model: model,
      contents: userInput,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: responseSchema,
      },
    });

    if (response.text) {
      return JSON.parse(response.text) as MatchResult;
    } else {
      throw new Error("Empty response from AI");
    }
  } catch (error) {
    console.error("Error matching class:", error);
    throw error;
  }
};

export interface MatchResult {
  status: 'success' | 'missing_info' | 'not_eligible' | 'location_unavailable';
  identified_location: 'Duluth' | 'Marietta' | null;
  identified_age: number | null;
  recommended_class_name: string | null;
  recommended_options: string[];
  reply_message_en: string;
  booking_action?: 'show_form' | null;
  class_id?: string | null;
}

