import React, { useState, useEffect } from 'react';
import { matchClass } from './services/geminiService';
import { MatchResult } from './types';
import { 
  Loader2, Send, MapPin, Info, AlertTriangle, 
  CheckCircle2, ArrowRight, User, Sparkles, 
  Instagram, Star, Trophy, Target, Zap, Menu, X,
  CalendarCheck, ShieldCheck, PlayCircle, BadgeCheck, Heart, MessageCircle, Grid, MoreHorizontal, Quote
} from 'lucide-react';

const App: React.FC = () => {
  // --- STATE ---
  const [childName, setChildName] = useState('');
  const [childAge, setChildAge] = useState('');
  const [location, setLocation] = useState('');

  const [loading, setLoading] = useState<boolean>(false);
  const [result, setResult] = useState<MatchResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Booking Form State
  const [bookingName, setBookingName] = useState('');
  const [bookingEmail, setBookingEmail] = useState('');
  const [bookingPhone, setBookingPhone] = useState('');
  const [bookingStatus, setBookingStatus] = useState<'idle' | 'sending' | 'sent'>('idle');

  // UI State
  const [scrolled, setScrolled] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  const locations = ["Gainesville", "Euharlee", "Marietta", "Cumming"];

  // Handle Scroll Effect for Header
  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!childAge || !location) return;

    setLoading(true);
    setError(null);
    setResult(null);
    setBookingStatus('idle');

    // Scroll to results area slightly
    const resultsElement = document.getElementById('results-area');
    if (resultsElement) resultsElement.scrollIntoView({ behavior: 'smooth', block: 'center' });

    const prompt = `My child's name is ${childName}. They are ${childAge} years old. We are looking for classes in ${location}.`;

    try {
      const data = await matchClass(prompt);
      setResult(data);
    } catch (err) {
      setError("Unable to connect to the scheduling system. Please check your internet.");
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleBookingSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!result || !result.class_id) return;
    setBookingStatus('sending');
    const payload = {
      parent_name: bookingName,
      parent_email: bookingEmail,
      parent_phone: bookingPhone,
      child_name: childName,
      class_id: result.class_id,
      location: result.identified_location,
      age: result.identified_age,
      recommended_class: result.recommended_class_name
    };
    console.log("SENDING TO WEBHOOK:", payload);
    setTimeout(() => {
      setBookingStatus('sent');
    }, 1500);
  };

  // Nav Links Configuration
  const navLinks = [
    { name: 'Methodology', href: '#methodology' },
    { name: 'Classes', href: '#finder' }, // Points to the finder
    { name: 'Instagram', href: '#instagram' }
  ];

  return (
    <div className="min-h-screen flex flex-col bg-gray-50 overflow-x-hidden">

      {/* --- HEADER --- */}
      <header 
        className={`fixed top-0 w-full z-50 transition-all duration-300 ${
          scrolled ? 'bg-white/95 backdrop-blur-md shadow-lg py-3' : 'bg-transparent py-5'
        }`}
      >
        <div className="max-w-6xl mx-auto px-6 flex items-center justify-between">
          {/* Logo Area */}
          <div className="flex items-center space-x-3">
            <div className="relative w-10 h-10 overflow-hidden rounded-full border-2 border-yellow-400 bg-white p-1">
              <img 
                src="https://traccoveredbridge.com/wp-content/uploads/2024/03/Covered_Bridge_logo.png" 
                alt="Logo" 
                className="w-full h-full object-contain"
              />
            </div>
            <div className={`font-heading font-extrabold uppercase tracking-tighter leading-none ${scrolled ? 'text-gray-900' : 'text-white'}`}>
              Covered<br/>Bridge
            </div>
          </div>

          {/* Desktop Nav */}
          <nav className="hidden md:flex items-center space-x-8">
            {navLinks.map((item) => (
              <a 
                key={item.name} 
                href={item.href}
                className={`text-sm font-bold uppercase tracking-wide hover:text-yellow-400 transition-colors ${scrolled ? 'text-gray-800' : 'text-white/90'}`}
              >
                {item.name}
              </a>
            ))}
            <a 
              href="#finder"
              className="bg-red-600 hover:bg-red-700 text-white text-xs font-black uppercase tracking-widest px-6 py-3 rounded-full shadow-lg hover:shadow-red-500/50 transition-all transform hover:-translate-y-0.5"
            >
              Free Trial
            </a>
          </nav>

          {/* Mobile Menu Toggle */}
          <button 
            className="md:hidden text-white"
